'use strict';
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{chromium}=require('playwright');
const root=path.resolve(__dirname,'..'),out=process.env.JY_LIUREN_REVIEW||path.join(require('node:os').tmpdir(),'jingyue-liuren-review');fs.mkdirSync(out,{recursive:true});
const types={'.html':'text/html','.js':'text/javascript','.mjs':'text/javascript','.css':'text/css','.svg':'image/svg+xml','.webp':'image/webp','.png':'image/png','.json':'application/json'};
const args=['--no-sandbox','--disable-dev-shm-usage','--enable-unsafe-swiftshader'].concat(process.env.JY_SINGLE_PROCESS?['--no-zygote','--single-process','--in-process-gpu','--disable-crash-reporter']:[]);
async function route(page,blocked=false){await page.route('**/*',async r=>{const u=new URL(r.request().url());if(u.origin!=='https://jingyue.uk')return r.abort();if(u.pathname.startsWith('/api/'))return r.fulfill({contentType:'application/json',body:'{"ok":true,"count":1,"live":1,"total":1}'});if(blocked&&u.pathname.endsWith('/liuren-scene.js'))return r.fulfill({status:503,body:''});const file=path.resolve(root,'.'+decodeURIComponent(u.pathname==='/'?'/index.html':u.pathname));if(!file.startsWith(root+path.sep))return r.abort();try{return await r.fulfill({body:fs.readFileSync(file),contentType:types[path.extname(file)]||'application/octet-stream'});}catch{return r.fulfill({status:404,body:''});}});}
async function cast(page){await page.goto('https://jingyue.uk',{waitUntil:'load'});await page.locator('[data-tool=liuren]').click();await page.locator('#lr-date').fill('2026-10-01');await page.locator('#lr-time').fill('22:06');await page.locator('#lr-cast').click();await page.locator('.lr-transmission').first().waitFor();}
async function touch(session,type,points){await session.send('Input.dispatchTouchEvent',{type,touchPoints:points.map((p,id)=>({x:p[0],y:p[1],id,radiusX:4,radiusY:4}))});}
async function arc(session,rect){const cx=rect.x+rect.width/2,cy=rect.y+rect.height/2,r=rect.width*.36;await touch(session,'touchStart',[[cx+r,cy]]);for(let i=1;i<=12;i++){const a=i/12*Math.PI/2;await touch(session,'touchMove',[[cx+r*Math.cos(a),cy+r*Math.sin(a)]]);}await touch(session,'touchEnd',[]);}
