  await page.touchscreen.tap(rect.x+rect.width/2,rect.y+rect.height*.8);assert.equal(await page.evaluate(()=>JYLiurenRoom.getState().selected),9,'rotated hit test retains native ground location');
  assert.equal(JSON.stringify(await page.evaluate(()=>JYLiurenRoom.getState().result)),native,'gestures leave all native facts intact');
  const cx=rect.x+rect.width/2,cy=rect.y+rect.height/2;await touch(session,'touchStart',[[cx-45,cy],[cx+45,cy]]);await touch(session,'touchMove',[[cx-55,cy+100],[cx+55,cy+100]]);await touch(session,'touchEnd',[]);
  let state=await page.evaluate(()=>JYLiurenRoom.getState());assert(state.pitch>.6&&state.zoom>1.1,'two-finger tilt and pinch zoom');
  await page.locator('.lr-instrument-canvas').focus();await page.keyboard.press('Home');assert.equal(await page.evaluate(()=>JYLiurenRoom.getState().pitch),0);assert.equal(await page.evaluate(()=>JYLiurenRoom.getState().zoom),1);
  await page.locator('[data-lr-action=layers]').click();await page.waitForFunction(()=>JYLiurenRoom.inspectScene().lift>.98);const heights=await page.evaluate(()=>JYLiurenRoom.inspectScene().layerHeights);assert(heights.generals>heights.sky&&heights.sky>.5,'physical layers lift separately');await page.screenshot({path:path.join(out,'liuren-3d-layers-390.png')});
  await page.locator('[data-lr-action=reset-view]').click();await page.emulateMedia({reducedMotion:'no-preference'});await page.locator('[data-lr-action=replay]').click();await page.waitForFunction(()=>JYLiurenRoom.inspectScene().phase===1&&JYLiurenRoom.inspectScene().skyVisible);assert.equal(await page.evaluate(()=>JYLiurenRoom.inspectScene().generalVisible),false);await page.screenshot({path:path.join(out,'liuren-3d-assembly-390.png')});
  await page.locator('[data-lr-action=skip]').click();await page.waitForFunction(()=>Math.abs(JYLiurenRoom.inspectScene().skyTurnDegrees-JYLiurenRoom.getState().result.rotation*30)<.05);
  await page.locator('#lr-main').evaluate(e=>{e.scrollTop=0;});await arc(session,await page.locator('.lr-instrument-canvas').boundingBox());const releaseAngle=await page.evaluate(()=>JYLiurenRoom.getState().angle);await page.waitForFunction(a=>JYLiurenRoom.getState().angle!==a,releaseAngle);await page.locator('[data-lr-action=reset-view]').click();await page.locator('[data-lr-quick="1"]').click();assert.equal(await page.evaluate(()=>JYLiurenRoom.getState().focusIndex),1);assert.equal(await page.locator('[data-lr-transmission="1"]').getAttribute('aria-pressed'),'true');await page.locator('[data-lr-action=trace]').click();await page.waitForFunction(()=>JYLiurenRoom.getState().tracing);await page.waitForFunction(()=>!JYLiurenRoom.getState().tracing&&JYLiurenRoom.getState().focusIndex===2);assert.equal(await page.locator('[data-lr-transmission="2"]').getAttribute('aria-pressed'),'true');
  await page.locator('#lr-main').evaluate(e=>{e.scrollTop=0;});await page.screenshot({path:path.join(out,'liuren-3d-trace-390.png')});
  assert.equal(JSON.stringify(await page.evaluate(()=>JYLiurenRoom.getState().result)),native);
